const STORAGE="koreanFriendApp_v1";
const state=loadState();
let studyIndex=0,studyItems=[],currentQuiz=null,speechRate=Number(state.rate||1),currentLib="hangul",chatScenario=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function defaultState(){return{correct:0,streak:0,lastStudy:"",items:{},rate:1}}
function loadState(){try{return Object.assign(defaultState(),JSON.parse(localStorage.getItem(STORAGE)||"{}"))}catch(e){return defaultState()}}
function saveState(){localStorage.setItem(STORAGE,JSON.stringify(state));updateDashboard()}
function todayKey(){return new Date().toISOString().slice(0,10)}
function daysBetween(a,b){return Math.round((new Date(b)-new Date(a))/86400000)}
function touchStudy(){const t=todayKey();if(state.lastStudy!==t){if(state.lastStudy&&daysBetween(state.lastStudy,t)===1)state.streak=(state.streak||0)+1;else state.streak=1;state.lastStudy=t}}
function itemKey(type,index,text){return type+"|"+index+"|"+text}
function getItemState(key){return state.items[key]||{correct:0,wrong:0,due:todayKey(),interval:0,last:""}}
function recordResult(key,ok){const x=getItemState(key),t=todayKey();if(ok){state.correct=(state.correct||0)+1;x.correct++;x.interval=Math.min((x.interval||0)+1,4);const ints=[1,3,7,14];x.due=new Date(Date.now()+ints[Math.max(0,x.interval-1)]*86400000).toISOString().slice(0,10)}else{x.wrong++;x.interval=0;x.due=t}x.last=t;state.items[key]=x;touchStudy();saveState()}
function dueCount(){const t=todayKey();return Object.values(state.items).filter(x=>x.due&&x.due<=t).length}
function updateDashboard(){if(!$("#streak"))return;$("#streak").textContent=state.streak||0;$("#correctCount").textContent=state.correct||0;$("#reviewDue").textContent="復習 "+dueCount()+"件";const coverage=Math.min(100,Math.round(Math.min((state.correct||0),100)*.75+Math.min(dueCount(),20)*1.25));$("#conversationPct").textContent=coverage+"%";$("#conversationBar").style.width=coverage+"%";$("#conversationHint").textContent=coverage<25?"ハングル→初級単語→短文の順で進めましょう。":coverage<60?"チャット表現を少しずつ混ぜてみましょう。":"覚えた表現をチャットで実際に使ってみましょう。"}
function speak(text){if(!("speechSynthesis"in window)){toast("このブラウザは音声合成に対応していません");return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang="ko-KR";u.rate=speechRate;speechSynthesis.speak(u)}
function toast(msg){const d=document.createElement("div");d.className="toast";d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),1800)}
function showView(name){$$(".view").forEach(x=>x.classList.remove("active"));$("#view-"+name).classList.add("active");$$(".tab").forEach(x=>x.classList.toggle("active",x.dataset.view===name));if(name==="study"){studyDirty=true;renderStudy()}if(name==="quiz")newQuiz();if(name==="review")renderReview();if(name==="library")renderLibrary();window.scrollTo({top:0,behavior:"smooth"})}
$$(".tab").forEach(b=>b.onclick=()=>showView(b.dataset.view));
$$("[data-go]").forEach(b=>b.onclick=()=>{showView(b.dataset.go);if(b.dataset.filter){if(b.dataset.filter==="hangul"){currentLib="hangul";renderLibrary()}else{$("#studyCategory").value=b.dataset.filter;renderStudy()}}});
function collectionFor(category){
 if(category==="beginner")return DATA.beginnerWords.map((x,i)=>({...x,type:"初級単語",key:itemKey("bw",i,x.ko)}));
 if(category==="intermediate")return DATA.intermediateWords.map((x,i)=>({...x,type:"中級単語",key:itemKey("iw",i,x.ko)}));
 if(category==="beginnerGrammar")return DATA.beginnerGrammar.map((x,i)=>({ko:x.grammar,ja:x.meaning,example:x.example,exampleJa:x.ja,type:"初級文法",key:itemKey("bg",i,x.grammar)}));
 if(category==="intermediateGrammar")return DATA.intermediateGrammar.map((x,i)=>({ko:x.grammar,ja:x.meaning,example:x.example,exampleJa:x.ja,type:"中級文法",key:itemKey("ig",i,x.grammar)}));
 if(category==="chat")return DATA.chat.map((x,i)=>({ko:x.term,ja:x.ja,example:x.ko,type:"チャット",key:itemKey("chat",i,x.term)}));
 return DATA.trends.map((x,i)=>({ko:x.term,ja:x.ja,example:x.ko,type:"流行語",key:itemKey("trend",i,x.term)}));
}
let studyQueue=[],studyCat="",studyPos=0,studyDirty=true,studyForce=null,studyHidden=0;
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function isHiddenCard(key){const x=state.items[key];return !!(x&&x.interval>0&&x.due>todayKey())}
function buildStudyQueue(){studyCat=$("#studyCategory").value;studyItems=collectionFor(studyCat);const vis=studyItems.filter(x=>!isHiddenCard(x.key));studyHidden=studyItems.length-vis.length;studyQueue=shuffle(vis);studyPos=0;studyDirty=false}
function requeueStudy(item){if(studyQueue.indexOf(item,studyPos+1)<0)studyQueue.splice(Math.min(studyPos+5,studyQueue.length),0,item)}
function renderStudy(){
if(studyDirty||$("#studyCategory").value!==studyCat)buildStudyQueue();
if(studyForce){const f=studyItems.find(x=>x.key===studyForce);studyForce=null;if(f){studyQueue=studyQueue.filter(x=>x!==f);studyQueue.unshift(f);studyPos=0}}
if(studyPos>=studyQueue.length&&studyQueue.length){buildStudyQueue();if(studyQueue.length)toast("一周しました。もう一度シャッフルします")}
if(!studyQueue.length){$("#studyMeta").textContent="表示できるカードがありません";$("#studyCard").innerHTML='<div class="panel"><h3>🎉 今日表示するカードはありません</h3><p>覚えたカードは復習日まで表示されません。別のカテゴリを選ぶか、明日また挑戦しましょう。</p></div>';return}
const item=studyQueue[studyPos];$("#studyMeta").textContent=item.type+" • "+(studyPos+1)+" / "+studyQueue.length+(studyHidden?"（覚えた"+studyHidden+"件は復習日まで非表示）":"");const ex=item.example?'<div class="example"><div class="ko">'+escapeHtml(item.example)+'</div>'+(item.exampleJa?'<div class="ja answer hidden">'+escapeHtml(item.exampleJa)+'</div>':"")+"</div>":"";$("#studyCard").innerHTML='<div class="card-type">'+escapeHtml(item.type)+'</div><div class="ko-word">'+escapeHtml(item.ko)+'</div><div class="ja-word answer hidden">'+escapeHtml(item.ja||"")+"</div>"+ex+'<div class="card-actions"><button class="primary" id="revealCard">👁 答えを見る</button><button class="primary" id="speakCard">🔊 韓国語を聞く</button><button class="ghost-btn" id="wrongCard">もう一度</button><button class="ghost-btn" id="knowCard">覚えた ✓</button><button class="ghost-btn" id="nextCard">次へ →</button></div>';$("#speakCard").onclick=()=>speak(item.example||item.ko);const reveal=()=>{$$("#studyCard .answer").forEach(x=>x.classList.remove("hidden"));const r=$("#revealCard");if(r)r.style.display="none"};$("#revealCard").onclick=reveal;$$("#studyCard .answer").forEach(x=>x.onclick=reveal);$("#knowCard").onclick=()=>{recordResult(item.key,true);studyPos++;renderStudy()};$("#wrongCard").onclick=()=>{recordResult(item.key,false);requeueStudy(item);reveal();toast("復習リストに追加しました")};$("#nextCard").onclick=()=>{studyPos++;renderStudy()}}
$("#studyCategory").onchange=()=>{studyIndex=0;renderStudy()};$("#studyRandom").onclick=()=>{studyDirty=true;renderStudy()};$$(".speed").forEach(b=>b.onclick=()=>{speechRate=Number(b.dataset.speed);state.rate=speechRate;saveState();$$(".speed").forEach(x=>x.classList.remove("active"));b.classList.add("active")});$("#speakTest").onclick=()=>speak("안녕하세요. 오늘도 같이 공부해요.");
function makeQuizPool(type){if(type==="word"||type==="wordReverse")return DATA.beginnerWords.concat(DATA.intermediateWords).map((x,i)=>({...x,key:itemKey("qword",i,x.ko)}));if(type==="grammar")return DATA.beginnerGrammar.concat(DATA.intermediateGrammar).map((x,i)=>({...x,ko:x.grammar,ja:x.meaning,key:itemKey("qgrammar",i,x.grammar)}));return DATA.chat.concat(DATA.trends).map((x,i)=>({...x,key:itemKey("qchat",i,x.term)}))}
function newQuiz(){const type=$("#quizType").value,pool=makeQuizPool(type),correct=pool[Math.floor(Math.random()*pool.length)],others=[];while(others.length<3){const x=pool[Math.floor(Math.random()*pool.length)];if(x!==correct&&!others.includes(x)&&x.ja!==correct.ja)others.push(x)}const options=[correct,...others].sort(()=>Math.random()-.5);currentQuiz={type,correct,options};const question=type==="wordReverse"?correct.ja:correct.ko;$("#quizBox").innerHTML='<div class="quiz-card"><div class="quiz-label">'+(type==="grammar"?"文法":"4択")+' • 正解を選んでください</div><div class="quiz-question">'+escapeHtml(question)+'</div><div class="options">'+options.map((o,i)=>'<button class="option" data-i="'+i+'">'+escapeHtml(type==="wordReverse"?o.ko:(type==="grammar"?o.meaning:o.ja))+"</button>").join("")+'</div><div id="quizResult"></div></div>';$$(".option").forEach(b=>b.onclick=()=>answerQuiz(Number(b.dataset.i)))}
function answerQuiz(i){const q=currentQuiz,chosen=q.options[i],ok=chosen===q.correct;$$(".option").forEach((b,j)=>{b.disabled=true;if(q.options[j]===q.correct)b.classList.add("correct");if(j===i&&!ok)b.classList.add("wrong")});recordResult(q.correct.key,ok);$("#quizResult").className="quiz-result "+(ok?"good":"bad");$("#quizResult").innerHTML=(ok?"正解！":"不正解。正解は <b>"+escapeHtml(q.type==="wordReverse"?q.correct.ko:(q.type==="grammar"?q.correct.meaning:q.correct.ja))+"</b>")+' <button class="ghost-btn" id="hearAnswer">🔊 聞く</button> <button class="primary" id="nextQuiz">次の問題</button>';$("#hearAnswer").onclick=()=>speak(q.correct.example||q.correct.ko);$("#nextQuiz").onclick=newQuiz}
$("#quizType").onchange=newQuiz;

const scenarios=[
{friend:"오늘 뭐 해?",friendJa:"今日は何するの？",replies:[["친구랑 카페에 갈 거야.","友達とカフェに行くよ。"],["집에서 쉬려고.","家で休むつもり。"],["아직 잘 모르겠어 ㅋㅋㅋ","まだよく分からない（笑）。"]]},
{friend:"이번 주말에 시간 있어?",friendJa:"今週末、時間ある？",replies:[["응 ㅇㅇ 시간 있어!","うん、あるよ！"],["미안, 이번 주말은 바빠.","ごめん、今週末は忙しい。"],["왜? 같이 놀러 가려고?","どうして？一緒に遊びに行くつもり？"]]},
{friend:"이거 진짜 맛있다 ㅋㅋㅋ",friendJa:"これ本当においしい（笑）",replies:[["ㄹㅇ 맛있어!","本当においしい！"],["나도 먹어보고 싶어.","私も食べてみたい。"],["꿀맛이다!","めちゃくちゃおいしい！"]]},
{friend:"지금 어디야?",friendJa:"今どこ？",replies:[["지금 집이야.","今、家だよ。"],["카페에 있어.","カフェにいるよ。"],["ㄱㄷ! 금방 갈게.","待って！すぐ行くよ。"]]},
{friend:"한국에 오면 뭐 하고 싶어?",friendJa:"韓国に来たら何したい？",replies:[["맛있는 거 먹고 싶어.","おいしいものを食べたい。"],["친구랑 같이 여행하고 싶어.","友達と一緒に旅行したい。"],["콘서트에 가고 싶어!","コンサートに行きたい！"]]}];
function newChat(){chatScenario=scenarios[Math.floor(Math.random()*scenarios.length)];$("#chatWindow").innerHTML='<div class="bubble friend"><div class="meta">친구</div>'+escapeHtml(chatScenario.friend)+'<br><small>'+escapeHtml(chatScenario.friendJa)+'</small> <button class="icon-btn" onclick="speak('+JSON.stringify(chatScenario.friend)+')">🔊</button></div>';$("#replyOptions").innerHTML=chatScenario.replies.map((r,i)=>'<button class="reply" data-i="'+i+'"><b>'+escapeHtml(r[0])+'</b><br><small>'+escapeHtml(r[1])+"</small></button>").join("");$$(".reply").forEach(b=>b.onclick=()=>sendReply(Number(b.dataset.i)));$("#chatFeedback").textContent="返信候補を1つ選ぶか、自分で韓国語を入力してください。"}
function highlightTerms(s){const found=[...DATA.chat,...DATA.trends].map(x=>x.term).filter(t=>s.includes(t));return found.length?found.join("・")+"を使えています":"自然な短文として使えています"}
function sendReply(i){const r=chatScenario.replies[i];$("#chatWindow").insertAdjacentHTML("beforeend",'<div class="bubble me"><div class="meta">自分</div>'+escapeHtml(r[0])+'<br><small>'+escapeHtml(r[1])+"</small></div>");speak(r[0]);touchStudy();saveState();$("#chatFeedback").innerHTML="<b>会話ポイント：</b> "+highlightTerms(r[0])+"。"}
$("#newChat").onclick=newChat;
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
if($("#voiceInput"))$("#voiceInput").onclick=()=>{
  if(!SpeechRecognition){toast("このブラウザは音声認識に対応していません。Chrome系ブラウザを推奨します。");return}
  const r=new SpeechRecognition();r.lang="ko-KR";r.interimResults=false;r.maxAlternatives=1;
  $("#voiceInput").textContent="🎙️";
  r.onresult=e=>{$("#chatInput").value=e.results[0][0].transcript;toast("韓国語を認識しました")};
  r.onerror=()=>toast("音声を認識できませんでした");
  r.onend=()=>{$("#voiceInput").textContent="🎤"};
  r.start();
};
$("#sendChat").onclick=()=>{const v=$("#chatInput").value.trim();if(!v)return;$("#chatWindow").insertAdjacentHTML("beforeend",'<div class="bubble me"><div class="meta">自分</div>'+escapeHtml(v)+"</div>");speak(v);$("#chatInput").value="";touchStudy();saveState();$("#chatFeedback").textContent="送信しました。まずは意味が通じる短い文を作ることを目標にしましょう。"};
function renderReview(){const entries=Object.entries(state.items).filter(([k,v])=>v.due<=todayKey()||v.wrong>0).sort((a,b)=>String(a[1].due).localeCompare(String(b[1].due)));if(!entries.length){$("#reviewList").innerHTML='<div class="panel"><h3>🎉 現在、復習対象はありません</h3><p>クイズかカード学習を進めると、ここに自動登録されます。</p></div>';return}$("#reviewList").innerHTML=entries.slice(0,100).map(([k,v])=>{const p=k.split("|");return'<div class="review-item"><div><span class="badge">'+escapeHtml(p[0])+'</span><b>'+escapeHtml(p.slice(2).join("|"))+'</b><small>正解 '+v.correct+"回 / ミス "+v.wrong+"回 / 次回 "+v.due+'</small></div><button class="ghost-btn" onclick="reviewOne('+JSON.stringify(k)+')">復習</button></div>'}).join("")}
function reviewOne(key){for(const cat of ["beginner","intermediate","chat","trends","beginnerGrammar","intermediateGrammar"]){const arr=collectionFor(cat),idx=arr.findIndex(x=>x.key===key);if(idx>=0){$("#studyCategory").value=cat;studyForce=key;showView("study");return}}toast("この項目を学習カードで開けませんでした")}
$("#reviewQuiz").onclick=()=>{if(!dueCount()){toast("復習対象はありません");return}showView("quiz");newQuiz()};

const pronouns=[["1人称","나","나는 (난) / 나를 (날) / 내가 / 나의→내"],["1人称","우리","우리는 (우린) / 우리를 (우릴) / 우리가 / 우리의"],["1人称 丁寧","저","저는 (전) / 저를 (절) / 제가 / 저의→제"],["1人称 丁寧","저희","저희는 (저흰) / 저희를 (저흴) / 저희가 / 저희의"],["2人称","너","너는 (넌) / 너를 (널) / 네가・니가 / 너의→네・니"],["2人称","너희","너희는 (너흰) / 너희를 (너흴) / 너희들이 / 너희들의"],["2人称","당신","당신은 / 당신을 / 당신이 / 당신의"],["3人称","그","그는 / 그를 / 그가 / 그의"],["3人称","그들","그들은 / 그들을 / 그들이 / 그들의"],["3人称","그녀","그녀는 / 그녀를 / 그녀가 / 그녀의"]];
const haeyo=[["基本","살다","살아요","住む"],["基本","좋다","좋아요","良い"],["基本","가다","가요","行く"],["基本","오다","와요","来る"],["基本","먹다","먹어요","食べる"],["基本","배우다","배워요","習う"],["基本","되다","돼요","成る"],["基本","마시다","마셔요","飲む"],["하다","사랑하다","사랑해요","愛する"],["ㄷ変則","깨닫다","깨달아요","悟る"],["ㄷ変則","듣다","들어요","聞く"],["ㅂ変則","가볍다","가벼워요","軽い"],["ㅂ変則","돕다","도와요","助ける"],["ㅅ変則","낫다","나아요","治る"],["ㅅ変則","짓다","지어요","作る"],["ㅎ変則","빨갛다","빨개요","赤い"],["ㅡ変則","나쁘다","나빠요","悪い"],["ㅡ変則","쓰다","써요","書く"],["르変則","모르다","몰라요","知らない"],["르変則","누르다","눌러요","押す"]];
function renderLibrary(){const q=($("#librarySearch").value||"").trim().toLowerCase();$$(".lib-tab").forEach(b=>b.classList.toggle("active",b.dataset.lib===currentLib));let html="";if(currentLib==="hangul"){html='<div class="mini-grid">'+DATA.hangul.vowels.map(x=>'<div class="mini"><div class="symbol">'+x[0]+'</div><b>'+x[1]+'</b><div>'+x[2]+"</div></div>").join("")+'</div><div class="mini-grid">'+DATA.hangul.consonants.map(x=>'<div class="mini"><div class="symbol">'+x[0]+'</div><b>'+x[1]+"</b></div>").join("")+"</div>"}else if(currentLib==="pronouns")html=table(["分類","語","活用"],pronouns);else if(currentLib==="haeyo")html=table(["分類","原形","해요体","意味"],haeyo);else{let rows=[];if(currentLib==="chat")rows=DATA.chat.filter(x=>matchQ(x,q)).map(x=>[x.term,x.ko,x.ja]);else if(currentLib==="trends")rows=DATA.trends.filter(x=>matchQ(x,q)).map(x=>[x.term,x.ko,x.ja]);else if(currentLib==="beginner")rows=DATA.beginnerWords.map((x,i)=>[i+1,x.ko,x.ja]);else if(currentLib==="intermediate")rows=DATA.intermediateWords.map((x,i)=>[i+1,x.ko,x.ja]);else if(currentLib==="beginnerGrammar")rows=DATA.beginnerGrammar.map(x=>[x.no,x.grammar,x.meaning,x.example,x.ja]);else rows=DATA.intermediateGrammar.map(x=>[x.no,x.grammar,x.meaning,x.example,x.ja]);if(q)rows=rows.filter(r=>r.some(v=>String(v).toLowerCase().includes(q)));html=table(currentLib.includes("Grammar")?["No.","文法","意味","例文","日本語"]:["No.","韓国語","日本語"],rows.slice(0,300));if(rows.length>300)html+='<div style="padding:12px;color:#6b7280">先頭300件を表示しています。検索欄で絞り込めます。</div>'}$("#libraryContent").innerHTML=html}
function table(headers,rows){return'<table class="data-table"><thead><tr>'+headers.map(h=>"<th>"+escapeHtml(h)+"</th>").join("")+"</tr></thead><tbody>"+rows.map(r=>"<tr>"+r.map((v,i)=>'<td class="'+(i===1?"ko":"")+'">'+escapeHtml(v)+"</td>").join("")+"</tr>").join("")+"</tbody></table>"}
function matchQ(x,q){return!q||Object.values(x).some(v=>String(v).toLowerCase().includes(q))}
$$(".lib-tab").forEach(b=>b.onclick=()=>{currentLib=b.dataset.lib;renderLibrary()});$("#librarySearch").oninput=renderLibrary;
$("#resetProgress").onclick=()=>{if(confirm("学習履歴をすべてリセットしますか？")){localStorage.removeItem(STORAGE);location.reload()}};
function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
updateDashboard();renderStudy();renderLibrary();newQuiz();newChat();
